internal class GUPPriceEngineJournalSearchEngine
{
    private static GUPPriceEngineJournalSearchEngine searchEngine;

    private GUPPriceEngineTradeAgreementLineCache tradeAgreementLineCache;
    private GUPPriceEngineMarginCodeLineCache marginCodeLineCache;
    private GUPPriceEngineAttributeGroupPriorityCache priorityCache;


}

Method.Source:
    public static GUPPriceEngineJournalSearchEngine getInstance(
        TransDate _date = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())) {

        if (searchEngine == null)
        {
            searchEngine = new GUPPriceEngineJournalSearchEngine();
        }

        searchEngine.doRefreshCache(_date);
        return searchEngine;
    }

/// <summary>
/// Expire the priority cache when table on the back is changed. 
/// </summary>
public static void expirePriority()
{
    if (searchEngine != null)
    {
        searchEngine.priorityCache = null;
        info("Priority cache is cleared.");
    }
}

/// <summary>
/// Expire trade agreement / price adjustment lines when table is changed.
/// </summary>
public static void expireTradeAgreementLines()
{
    if (searchEngine != null)
    {
        searchEngine.tradeAgreementLineCache = null;
        info("Trade Agreement line cache is cleared.");
    }
}

public static void expireMarginCodeLines()
{
    if (searchEngine != null)
    {
        searchEngine.marginCodeLineCache = null;
        info("Margin code line cache is cleared.");
    }
}

    public void doRefreshCache(TransDate _date)
    {
        if (priorityCache == null)
        {
            priorityCache = new GUPPriceEngineAttributeGroupPriorityCache();
        }

        // Refresh cache on specific date.
        if (tradeAgreementLineCache == null || tradeAgreementLineCache.parmCachedDate() != _date)
        {
            tradeAgreementLineCache = null;
            GUPPriceEngineTradeAgreementLineCache lineCache = new GUPPriceEngineTradeAgreementLineCache(_date);
            tradeAgreementLineCache = lineCache;
        }

        if (marginCodeLineCache == null || marginCodeLineCache.parmCachedDate() != _date)
        {
            marginCodeLineCache = null;
            GUPPriceEngineMarginCodeLineCache lineCache = new GUPPriceEngineMarginCodeLineCache(_date);
            marginCodeLineCache = lineCache;
        }
    }

    public GUPPriceEnginePrematchObject doSearch(SalesTable _salesTable, SalesLine _salesLine)
    {
        TransDate _date = _salesLine.priceDate();

        // Refresh when try calculating lines on another date.
        this.doRefreshCache(_date);

        GUPPriceComponent tradeAgreementComponent = GUPPriceComponent::SalesTradeAgreement;
        str tradeAgreementComponentCodeName = priorityCache.getPriceComponentCodeNameByPriceComponent(tradeAgreementComponent);

        GUPPriceEnginePrematchObject prematchObject = this.initializePrematchObject(_salesTable, _salesLine);

        // Records which tables need to be loaded.
        Map datasourceRequired = new Map(Types::String, Types::AnyType);
        Set tradeAgreementLineRecIdSet = new Set(Types::Int64);
        Set marginCodeLineRecIdSet = new Set(Types::Int64);

        // Filter trade agreements, return list<GUPPriceEngineTradeAgreementLineAggregation>.
        // A line contains exactly one header rule (for salesTable) and one line rule (for salesLine).
        List filteredTradeAgreementList = GUPPriceEngineTradeAgreementLineFilter::getInstance().filterJournalLineList(
            _salesTable, 
            _salesLine,
            tradeAgreementLineCache.parmLineList(),
            tradeAgreementLineRecIdSet,
            tradeAgreementComponentCodeName,
            priorityCache);
        prematchObject.parmTradeAgreementJournalLineList(filteredTradeAgreementList);

        this.checkAndAddDatasourceRequired(datasourceRequired,
            tradeAgreementLineCache.parmPricingAttributeDatasourceMap(),
            tradeAgreementLineRecIdSet);

        // Filter price adjustment lines.
        List filteredMarginComponentList = GUPPriceEngineMarginCodeLineFilter::getInstance().filterMarginCodeLineList(
            _salesTable,
            _salesLine,
            marginCodeLineCache.parmLineList(),
            marginCodeLineRecIdSet,
            priorityCache);
        prematchObject.parmMarginComponentList(filteredMarginComponentList);

        this.checkAndAddDatasourceRequired(datasourceRequired,
            marginCodeLineCache.parmPricingAttributeDatasourceMap(),
            marginCodeLineRecIdSet);

        // Load records for all attribute-related tables.
        this.loadSalesData(_salesTable,
            _salesLine,
            datasourceRequired,
            prematchObject.parmSalesTableRelatedDataMap(),
            prematchObject.parmSalesLineRelatedDataMap());

        return prematchObject;
    }

    private void checkAndAddDatasourceRequired(Map _datasourceRequired, 
        Map _cacheDatasourceMap,
        Set _validLineRecIdSet)
    {
        
        MapEnumerator enumerator = _cacheDatasourceMap.getEnumerator();
        while (enumerator.moveNext())
        {
            GUPPriceEngineDatasourceAggregationObject datasource = enumerator.currentValue();

            // Already need to load. Skip.
            if (_datasourceRequired.exists(datasource.parmDatasourceId()))
            {
                continue;
            }

            // Current salesTable/salesLine not using selected datasource (i.e. table), skip.
            if (Set::intersection(datasource.parmLineRecIdSet(), _validLineRecIdSet).empty())
            {
                continue;
            }

            _datasourceRequired.add(datasource.parmDatasourceId(), datasource);
        }
    }

    /// <summary>
    /// Load all data related to an sales order / sales line, that may useful in rule matching calculations.
    /// </summary>
    /// <param name = "_salesTable">The chosen sales order.</param>
    /// <param name = "_salesLine">The chosen sales line.</param>
    /// <param name = "_datasourceMap">The datasource map</param>
    /// <param name = "_salesTableRelatedData">Sales table related data.</param>
    /// <param name = "_salesLineRelatedData">Sales line related data.</param>
    private void loadSalesData (Common _salesTable, 
        Common _salesLine,  
        Map _datasourceMap,
        Map _salesTableRelatedData, 
        Map _salesLineRelatedData)
    {
        MapEnumerator enumerator = _datasourceMap.getEnumerator();

        // TODO concurrent.

        while (enumerator.moveNext())
        {
            GUPPriceEngineDatasourceAggregationObject datasource = enumerator.currentValue();

            Common pricingObject = 
                (datasource.parmSourceLevel() == GUPPricingAttributeSourceLevel::Header) ? 
                _salesTable : 
                _salesLine;

            Map relatedDataMap = 
                (datasource.parmSourceLevel() == GUPPricingAttributeSourceLevel::Header) ?
                _salesTableRelatedData :
                _salesLineRelatedData;
            
            GUPIPricingAttribute datasourceAttribute = datasource.parmDatasourceAttribute();

            // Class-based attribute will only return one table record, joined from salesTable or salesLine.
            if (classIdGet(datasourceAttribute) != classNum(GUPPricingAttributeEcoResAttribute))
            {
                Common tableRecord = datasourceAttribute.getRecord(pricingObject);
                relatedDataMap.add(datasource.parmDatasourceId(), new GUPPriceEngineRelatedDataObject(tableRecord));
            }
            // EcoResAttribute return multiple lines, each has unique key as AttributeName + AttributeTypeName.
            else 
            {
                GUPPricingAttributeEcoResAttribute ecoResAttribute = datasourceAttribute;
                relatedDataMap.add(datasource.parmDatasourceId(), new GUPPriceEngineRelatedDataObject(null, ecoResAttribute.getTableRecordMap(pricingObject)));
            }
        }
    }

    private GUPPriceEnginePrematchObject initializePrematchObject(SalesTable _salesTable, SalesLine _salesLine)
    {
        GUPPriceEnginePrematchObject prematchObject = new GUPPriceEnginePrematchObject(_salesTable, _salesLine);

        // Key = field id, Value = GUPPriceEngineRelatedDataObject.
        Map salesTableRelatedData = new Map(Types::String, Types::AnyType);
        prematchObject.parmSalesTableRelatedDataMap(salesTableRelatedData);

        Map salesLineRelatedData = new Map(Types::String, Types::AnyType);
        prematchObject.parmSalesLineRelatedDataMap(salesLineRelatedData);

        return prematchObject;
    }
